require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/unified_experience_v1100.php';require_once __DIR__.'/app/layout.php';require_once __DIR__.'/app/local_deals_loyalty_v1050.php';$u=current_user();if(!$u){header('Location: /login.php?redirect='.rawurlencode('/merchant-deals-v1050.php'));exit;}$uid=(int)$u['id'];$tid=sk1050_tid();$biz=sk1050_businesses_for_user($uid);$msg='';try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();$a=$_POST['action']??'';if($a==='create'){if(!sk1050_on('merchant_self_service'))throw new RuntimeException('Merchant deal creation is disabled.');$bid=(int)($_POST['business_id']??0);$owns=false;foreach($biz as $b)if((int)$b['id']===$bid)$owns=true;if(!$owns)throw new RuntimeException('Choose one of your businesses.');$title=trim((string)($_POST['title']??''));if($title==='')throw new RuntimeException('Title is required.');$status=sk1050_on('approval_required')?'pending':'active';$q=db()->prepare('INSERT INTO local_deals_v1050(tenant_id,business_id,owner_user_id,title,description,coupon_code,discount_type,discount_value,minimum_spend,terms_text,starts_at,ends_at,usage_limit,per_user_limit,status,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$tid,$bid,$uid,$title,trim((string)$_POST['description']),trim((string)$_POST['coupon_code']),$_POST['discount_type']??'percent',(float)$_POST['discount_value'],(float)$_POST['minimum_spend'],trim((string)$_POST['terms_text']),$_POST['starts_at'],$_POST['ends_at'],(int)$_POST['usage_limit'],max(1,(int)$_POST['per_user_limit']),$status,$uid]);$msg=$status==='pending'?'Deal submitted for admin approval.':'Deal published.';}elseif($a==='redeem'){$r=sk1050_redeem((string)($_POST['claim_code']??''),$uid);$msg=$r['message'];}}}catch(Throwable $e){$msg=$e->getMessage();}$q=db()->prepare('SELECT d.*,b.name business_name FROM local_deals_v1050 d LEFT JOIN businesses b ON b.id=d.business_id WHERE d.tenant_id=? AND d.owner_user_id=? ORDER BY d.id DESC LIMIT 100');$q->execute([$tid,$uid]);$deals=$q->fetchAll()?:[];page_start('Merchant Deals',false);?><?php sk1100_public_assets();sk1100_render_public_subnav();?><link rel="stylesheet" href="/assets/deals-loyalty-v1050.css?v=1050"><main class="dl1050"><section class="wallet-head"><div><span>MERCHANT CENTER</span><h1>Deals & Redemptions</h1><p>Create local offers and redeem customer coupon codes.</p></div><a href="/deals-v1050.php">Public deals</a></section><?php if($msg):?><div class="notice"><?=sk1050_h($msg)?></div><?php endif;?><div class="two-col"><section class="panel"><h2>Redeem customer coupon</h2><form method="post" class="form"><input type="hidden" name="_csrf" value="<?=sk1050_h(csrf_token())?>"><input type="hidden" name="action" value="redeem"><label>Claim code<input name="claim_code" placeholder="SKXXXXXXXXXXXX" required></label><button>Verify & Redeem</button></form></section><section class="panel"><h2>Create a deal</h2><?php if(!$biz):?><p>You need an owned business listing before creating merchant deals.</p><?php else:?><form method="post" class="form"><input type="hidden" name="_csrf" value="<?=sk1050_h(csrf_token())?>"><input type="hidden" name="action" value="create"><label>Business<select name="business_id"><?php foreach($biz as $b):?><option value="<?=(int)$b['id']?>"><?=sk1050_h($b['name'])?></option><?php endforeach;?></select></label><label>Deal title<input name="title" required></label><label>Description<textarea name="description"></textarea></label><div class="form-row"><label>Discount type<select name="discount_type"><option value="percent">Percent off</option><option value="amount">Amount off</option><option value="fixed_price">Fixed price</option></select></label><label>Value<input type="number" step="0.01" name="discount_value" required></label></div><div class="form-row"><label>Starts<input type="datetime-local" name="starts_at" required></label><label>Ends<input type="datetime-local" name="ends_at" required></label></div><div class="form-row"><label>Minimum spend<input type="number" step="0.01" name="minimum_spend" value="0"></label><label>Usage limit<input type="number" name="usage_limit" value="0"></label></div><label>Coupon text (optional)<input name="coupon_code"></label><label>Terms<textarea name="terms_text"></textarea></label><input type="hidden" name="per_user_limit" value="1"><button>Create deal</button></form><?php endif;?></section></div><section><h2>My offers</h2><div class="ledger"><?php foreach($deals as $d):?><div><span><b><?=sk1050_h($d['title'])?></b> · <?=sk1050_h($d['business_name'])?></span><strong><?=sk1050_h(ucfirst($d['status']))?></strong><small><?=number_format((int)$d['claimed_count'])?> claims · <?=number_format((int)$d['redeemed_count'])?> redeemed</small></div><?php endforeach;?></div></section></main><?php sk1100_render_ai_widget('public');require __DIR__.'/app/end.php';?>
